import * as THREE from "three";
import { backgroundFragment, planeFragment, planeVertex, fullscreenVertex } from "./shaders";

// The shaders work in raw sRGB values (as the CSS tokens are), so skip three's linear conversion.
THREE.ColorManagement.enabled = false;

const TAU = Math.PI * 2;
const RADIUS = 3.3;
const PLANE_W = 2.3;
const PLANE_H = PLANE_W * 0.625;

// Wraps an angle into [-PI, PI).
const wrap = (a) => (((a % TAU) + TAU * 1.5) % TAU) - Math.PI;

/**
 * Builds the project ring on `canvas` and runs it until destroy() is called.
 * React talks to it through the returned controls and the callbacks.
 */
export default function createOrbit({ canvas, stage, images, onFrontChange, onSelect }) {
  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  } catch (e) {
    return null;
  }

  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const cssVar = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  const small = window.matchMedia("(max-width: 720px)").matches;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, small ? 1.5 : 1.75));
  renderer.autoClear = false;

  // Background: a slow noise field tinted by the page tokens.
  const bgScene = new THREE.Scene();
  const bgCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const bgUniforms = {
    t: { value: 0 },
    res: { value: new THREE.Vector2() },
    mouse: { value: new THREE.Vector2(0.5, 0.5) },
    c1: { value: new THREE.Color() },
    c2: { value: new THREE.Color() },
    c3: { value: new THREE.Color() },
  };
  const bgGeometry = new THREE.PlaneGeometry(2, 2);
  const bgMaterial = new THREE.ShaderMaterial({
    uniforms: bgUniforms,
    depthWrite: false,
    vertexShader: fullscreenVertex,
    fragmentShader: backgroundFragment,
  });
  bgScene.add(new THREE.Mesh(bgGeometry, bgMaterial));

  // Ring of project planes.
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, 1, 0.1, 100);
  const ring = new THREE.Group();
  ring.rotation.x = 0;
  scene.add(ring);

  const count = images.length;
  const step = TAU / count;
  const loader = new THREE.TextureLoader();
  const planeGeometry = new THREE.PlaneGeometry(PLANE_W, PLANE_H, small ? 24 : 48, small ? 12 : 24);
  const textures = [];
  const planes = images.map((src, i) => {
    const uniforms = {
      tex: { value: null },
      hover: { value: 0 },
      vel: { value: 0 },
      t: { value: 0 },
      op: { value: 1 },
      sat: { value: 0.55 },
    };
    const material = new THREE.ShaderMaterial({
      uniforms,
      transparent: true,
      side: THREE.DoubleSide,
      vertexShader: planeVertex,
      fragmentShader: planeFragment,
    });
    loader.load(src, (texture) => {
      texture.minFilter = THREE.LinearFilter;
      textures.push(texture);
      uniforms.tex.value = texture;
    });
    const mesh = new THREE.Mesh(planeGeometry, material);
    const angle = i * step;
    mesh.position.set(Math.sin(angle) * RADIUS, 0, Math.cos(angle) * RADIUS);
    mesh.rotation.y = angle;
    mesh.userData = { index: i, angle, uniforms };
    ring.add(mesh);
    return mesh;
  });

  // Motion state. Rotation is driven by velocity, or eased toward snapTo.
  let rotation = 0;
  let velocity = 0;
  let snapTo = null;
  let dragging = false;
  let lastX = 0;
  let travelled = 0;
  let hovered = -1;
  let focus = -1;
  let front = -1;
  let cameraZ = 9;
  let cameraTarget = 9;
  let frame = 0;
  let onScreen = true;
  const pointer = new THREE.Vector2(-9, -9);
  const raycaster = new THREE.Raycaster();
  const clock = new THREE.Clock();

  function resize() {
    const w = stage.clientWidth;
    const h = stage.clientHeight;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    const fit = (PLANE_W * 1.25) / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * camera.aspect);
    cameraTarget = RADIUS + Math.max(5.2, fit);
    ring.position.y = w < 720 ? -0.15 : -0.35;
    camera.updateProjectionMatrix();
    const pr = renderer.getPixelRatio();
    bgUniforms.res.value.set(w * pr, h * pr);
  }

  function readColors() {
    bgUniforms.c1.value.set(cssVar("--bg"));
    bgUniforms.c2.value.set(cssVar("--bg-2"));
    bgUniforms.c3.value.set(cssVar("--accent"));
  }

  function goTo(index) {
    const target = -(index * step);
    snapTo = rotation + wrap(target - rotation);
  }

  // Horizontal drag spins the ring; vertical page scroll is left alone (touch-action: pan-y).
  function onPointerDown(e) {
    dragging = true;
    travelled = 0;
    lastX = e.clientX;
    snapTo = null;
    canvas.classList.add("is-grabbing");
    canvas.setPointerCapture(e.pointerId);
  }
  function onPointerMove(e) {
    const r = canvas.getBoundingClientRect();
    pointer.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
    bgUniforms.mouse.value.set((e.clientX - r.left) / r.width, 1 - (e.clientY - r.top) / r.height);
    if (!dragging || focus >= 0) return;
    const dx = e.clientX - lastX;
    lastX = e.clientX;
    travelled += Math.abs(dx);
    velocity = dx * 0.0045;
    rotation += velocity;
  }
  function onPointerUp() {
    if (!dragging) return;
    dragging = false;
    canvas.classList.remove("is-grabbing");
    if (travelled < 6 && hovered >= 0) onSelect(hovered);
  }
  function onPointerLeave() {
    pointer.set(-9, -9);
  }

  const darkQuery = window.matchMedia("(prefers-color-scheme: dark)");
  const themeObserver = new MutationObserver(readColors);
  canvas.addEventListener("pointerdown", onPointerDown);
  canvas.addEventListener("pointermove", onPointerMove);
  canvas.addEventListener("pointerup", onPointerUp);
  canvas.addEventListener("pointercancel", onPointerUp);
  canvas.addEventListener("pointerleave", onPointerLeave);
  window.addEventListener("resize", resize);
  darkQuery.addEventListener("change", readColors);
  themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  resize();
  readColors();

  function tick() {
    const t = clock.getElapsedTime();

    if (!dragging) {
      if (snapTo !== null) {
        rotation += (snapTo - rotation) * (reduce ? 1 : 0.09);
        velocity = 0;
        if (Math.abs(snapTo - rotation) < 0.0005) rotation = snapTo;
      } else {
        velocity *= 0.93;
        rotation += velocity;
        if (Math.abs(velocity) < 0.0008 && !reduce && focus < 0) rotation += 0.0016;
      }
    }
    ring.rotation.y = rotation;

    // Whichever plane faces the camera is the "current" project.
    let best = 0;
    let bestDistance = Infinity;
    planes.forEach((m) => {
      const d = Math.abs(wrap(m.userData.angle + rotation));
      if (d < bestDistance) {
        bestDistance = d;
        best = m.userData.index;
      }
    });
    if (best !== front) {
      front = best;
      onFrontChange(front);
    }

    // Sit above the ring and look down so the far side shows over the front plane.
    camera.position.set(0, 2.1, cameraZ);
    camera.lookAt(0, ring.position.y - 0.25, 0);
    camera.updateMatrixWorld();
    raycaster.setFromCamera(pointer, camera);
    const hit = focus < 0 ? raycaster.intersectObjects(planes)[0] : null;
    hovered = hit ? hit.object.userData.index : -1;
    canvas.classList.toggle("is-pointing", hovered >= 0 && !dragging);

    // Opening a project dollies in and slides the ring clear of the panel.
    const wide = stage.clientWidth > 900;
    const zGoal = focus >= 0 ? cameraTarget - 0.5 : cameraTarget;
    const xGoal = focus >= 0 && wide ? -0.55 : 0;
    const ease = reduce ? 1 : 0.06;
    cameraZ += (zGoal - cameraZ) * ease;
    ring.position.x += (xGoal - ring.position.x) * ease;

    const pending = snapTo !== null ? (snapTo - rotation) * 0.09 : velocity;
    const speed = Math.min(Math.abs(dragging ? velocity : pending) * 18, 1);
    planes.forEach((m) => {
      const u = m.userData.uniforms;
      const i = m.userData.index;
      const active = i === hovered || i === focus;
      const facing = Math.max(0, Math.cos(wrap(m.userData.angle + rotation)));
      u.hover.value += ((active ? 1 : 0) - u.hover.value) * 0.1;
      u.vel.value += ((reduce ? 0 : speed) - u.vel.value) * 0.15;
      u.t.value = t;
      const opacityGoal = focus >= 0 && i !== focus ? 0.08 : 0.55 + 0.45 * facing;
      u.op.value += (opacityGoal - u.op.value) * 0.1;
      u.sat.value = 0.45 + 0.4 * facing;
      m.scale.setScalar(1 + u.hover.value * 0.05);
    });

    bgUniforms.t.value = reduce ? 0 : t;
    renderer.clear();
    renderer.render(bgScene, bgCamera);
    renderer.clearDepth();
    renderer.render(scene, camera);
    frame = requestAnimationFrame(tick);
  }

  // Only render while the stage is visible and the tab is in front.
  function syncLoop() {
    const shouldRun = onScreen && !document.hidden;
    if (shouldRun && !frame) {
      clock.getDelta();
      tick();
    } else if (!shouldRun && frame) {
      cancelAnimationFrame(frame);
      frame = 0;
    }
  }
  const visibility = new IntersectionObserver(([entry]) => {
    onScreen = entry.isIntersecting;
    syncLoop();
  });
  visibility.observe(stage);
  document.addEventListener("visibilitychange", syncLoop);
  syncLoop();

  return {
    next: () => goTo((front + 1) % count),
    prev: () => goTo((front - 1 + count) % count),
    focus(index) {
      if (index >= 0) goTo(index);
      focus = index;
    },
    destroy() {
      cancelAnimationFrame(frame);
      frame = 0;
      visibility.disconnect();
      document.removeEventListener("visibilitychange", syncLoop);
      canvas.removeEventListener("pointerdown", onPointerDown);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerup", onPointerUp);
      canvas.removeEventListener("pointercancel", onPointerUp);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      window.removeEventListener("resize", resize);
      darkQuery.removeEventListener("change", readColors);
      themeObserver.disconnect();
      planes.forEach((m) => m.material.dispose());
      textures.forEach((tx) => tx.dispose());
      planeGeometry.dispose();
      bgGeometry.dispose();
      bgMaterial.dispose();
      renderer.dispose();
    },
  };
}
