export const fullscreenVertex = /* glsl */ `
  void main() { gl_Position = vec4(position, 1.0); }
`;

// Domain-warped noise in the page's background and accent colours, brightened near the pointer.
export const backgroundFragment = /* glsl */ `
  uniform float t;
  uniform vec2 res, mouse;
  uniform vec3 c1, c2, c3;
  float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
  float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
  }
  float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.02; a *= 0.5; }
    return v;
  }
  void main() {
    vec2 uv = gl_FragCoord.xy / res;
    vec2 ar = vec2(res.x / res.y, 1.0);
    vec2 q = uv * ar * 1.6;
    float w = fbm(q + vec2(t * 0.04, -t * 0.03));
    float f = fbm(q * 1.3 + w * 1.8 + vec2(-t * 0.02, t * 0.025));
    vec3 col = mix(c1, c2, smoothstep(0.25, 0.85, f));
    col = mix(col, c3, smoothstep(0.62, 0.98, f) * 0.28);
    col += c3 * 0.10 * smoothstep(0.55, 0.0, distance(uv * ar, mouse * ar));
    col += (hash(uv * res + t) - 0.5) * 0.035;
    gl_FragColor = vec4(col, 1.0);
  }
`;

// Curves each plane onto the ring and ripples it on hover and while spinning.
export const planeVertex = /* glsl */ `
  uniform float hover, t, vel;
  varying vec2 vUv;
  void main() {
    vUv = uv;
    vec3 p = position;
    p.z += -pow(p.x, 2.0) * 0.09;
    p.z += sin(uv.x * 9.0 + t * 3.0) * 0.035 * hover + sin(uv.y * 6.0 + t * 2.0) * 0.02 * hover;
    p.z += sin(uv.y * 3.14159) * vel * 0.25;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
  }
`;

// RGB split grows with spin speed; planes away from the camera lose colour.
export const planeFragment = /* glsl */ `
  uniform sampler2D tex;
  uniform float hover, vel, op, sat;
  varying vec2 vUv;
  void main() {
    vec2 uv = vUv;
    float s = 0.0008 + vel * 0.03 + hover * 0.0015;
    vec3 c = vec3(texture2D(tex, uv + vec2(s, 0.0)).r, texture2D(tex, uv).g, texture2D(tex, uv - vec2(s, 0.0)).b);
    float l = dot(c, vec3(0.299, 0.587, 0.114));
    c = mix(vec3(l), c, mix(sat, 1.0, hover));
    vec2 e = smoothstep(0.0, 0.02, uv) * smoothstep(0.0, 0.02, 1.0 - uv);
    gl_FragColor = vec4(c * (0.82 + 0.18 * hover), op * e.x * e.y);
  }
`;
